[
  {
    "statement": "Based on the available evidence, fertilizer addition appears to be more consistently effective for increasing vegetation cover than mycorrhiza inoculation.",
    "citations": []
  },
  {
    "statement": "For fertilizer treatments, six of nine studies found that adding fertilizer alongside sowing or planting increased vegetation cover in all or some cases.",
    "citations": [
      "3427"
    ]
  },
  {
    "statement": "One study in Iceland found that adding fertilizer and sowing seeds increased vegetation cover in two of three cases.",
    "citations": [
      "1704"
    ]
  },
  {
    "statement": "For mycorrhiza inoculation, the evidence is more mixed and primarily relates to inoculation before rather than after seeding.",
    "citations": []
  },
  {
    "statement": "One study found that inoculating soil with mycorrhizal fungi before sowing seeds initially increased vegetation cover.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "After three years, in the same study, vegetation cover did not differ between areas that were inoculated with mycorrhizal fungi and areas that were not inoculated.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "Another study found that adding soil microbes and nutrients when planting grass plugs did not change the overall cover of herbaceous species.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "One study found that adding mycorrhiza to soil and sowing seeds increased the abundance of target species considered a local conservation priority.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "The available studies do not provide direct comparative evidence between fertilizer and mycorrhiza inoculation specifically after seeding for vegetation cover outcomes.",
    "citations": []
  }
]
